/* Bench on your phone. Solanum: Ivory ground (Slate in the dark), hairline cards, no shadows.
Clay is for shapes and fills only; clay as words uses --clay-ink. No inline styles anywhere (CSP). */
:root {
color-scheme: light dark;
--ground: #faf9f5;
--card: #fff;
--ink: #141413;
--body: #3d3d3a;
--muted: #5e5d59;
--faint: #73726c;
