.bar.scrolled .bar-t { opacity: 1; }
.icon-btn, .back {
min-width: 44px;
min-height: 44px;
display: inline-flex;
align-items: center;
justify-content: center;
gap: 2px;
border: 0;
background: none;
padding: 0 8px;
color: var(--clay-ink);
text-decoration: none;
