}
h1:focus { outline: none; }
.tight-sub { margin: 0 0 14px; }
.sec { margin: 0 0 26px; }
.sec-h {
display: flex;
align-items: center;
gap: 8px;
margin: 0 4px 8px;
font: 500 max(11px, .7rem)/1.2 var(--mono);
