.plist > .quiet { margin: 12px 4px 0; }
.group .row .dot, .group .row > .ico:first-child { flex: none; }
.mk { flex: none; display: grid; place-items: center; width: 20px; }
.kind-ic { flex: none; display: grid; place-items: center; width: 32px; height: 32px; border-radius: 8px; background: var(--fill); color: var(--muted); }
.fname { overflow-wrap: anywhere; word-break: break-word; }
.scrim.top { align-items: flex-start; padding-top: calc(env(safe-area-inset-top) + 16px); }
.sheet.wide { max-width: 520px; }
.box.left { text-align: left; }
.box.left .sec-h { margin: 0 0 8px; }
.ns-text {
display: block;
width: 100%;
min-height: 128px;
margin: 0 0 12px;
padding: 10px 12px;
border: 1px solid var(--line);
border-radius: 12px;
background: var(--ground);
color: var(--ink);
font-size: max(16px, 1rem);
line-height: 1.35;
resize: none;
}
.ns-text::placeholder { color: var(--muted); }
.ns-opts { margin-bottom: 12px; }
.ns-photo { margin: 0 0 12px; }
.ns-photo .photo-note { margin-left: 2px; }
.btn.small.ns-cam { display: inline-flex; min-height: 44px; }
.sheet .box .msg { margin: 0 0 10px; }
.hist-top { display: flex; flex-direction: column; align-items: center; justify-content: center; min-height: 32px; margin: 0 0 8px; }
.hist-top .quiet { margin: 0; text-align: center; }
.hist-begin { margin: 0 4px 10px; font-size: .82rem; color: var(--muted); text-align: center; }
.hist > .qrow::before { display: none; }
.qrow { display: flex; align-items: flex-start; gap: 8px; padding: 7px 16px; font-size: .84rem; line-height: 1.35; color: var(--muted); }
.qrow .ico { margin-top: 1px; }
.qrow span { min-width: 0; overflow-wrap: anywhere; }
.turn-acts { display: flex; align-items: center; gap: 16px; }
.turn-acts:empty { display: none; }
.tou .md { font-size: .92rem; color: var(--muted); }
.quiet-who { display: inline-flex; align-items: center; gap: 6px; font-weight: 500; font-size: .82rem; color: var(--muted); }
.chips { display: flex; flex-wrap: wrap; gap: 8px; margin: 6px 0 2px; }
.chip {
display: inline-flex;
align-items: center;
gap: 6px;
min-height: 40px;
max-width: 100%;
padding: 0 12px;
border: 1px solid var(--line);
border-radius: 10px;
background: var(--ground);
color: var(--ink);
font-size: .86rem;
text-decoration: none;
}
.chip .ico { color: var(--muted); flex: none; }
.chip-n { min-width: 0; max-width: 14em; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.chip-s { flex: none; color: var(--muted); font-size: .78rem; }
.md-img { display: block; max-width: 100%; height: auto; margin: .4em 0; border-radius: 8px; }
.thumbs { display: grid; grid-template-columns: repeat(auto-fill, minmax(104px, 1fr)); gap: 8px; }
.thumb { display: grid; place-items: center; aspect-ratio: 1; overflow: hidden; border: 1px solid var(--line); border-radius: 10px; background: var(--fill); }
.thumb img { display: block; width: 100%; height: 100%; object-fit: cover; }
.thumb .big { width: 32px; height: 32px; color: var(--muted); }
.viewer-img-wrap { margin: 0 0 14px; overflow: hidden; border: 1px solid var(--line); border-radius: 12px; background: var(--card); }
.viewer-img-wrap .quiet { margin: 14px; }
.viewer-img { display: block; width: 100%; height: auto; }
.viewer-tools { margin: 0 0 8px; }
.btn.small { display: inline-flex; width: auto; min-height: 40px; padding: 0 16px; font-weight: 500; }
.btn[aria-pressed="true"] { border-color: var(--clay); background: var(--tint); }
.viewer-pre {
margin: 0 0 12px;
padding: 12px 14px;
max-width: 100%;
max-height: 70vh;
overflow: auto;
-webkit-overflow-scrolling: touch;
white-space: pre;
tab-size: 4;
border: 1px solid var(--line);
border-radius: 12px;
background: var(--card);
color: var(--ink);
font: .85rem/1.45 var(--mono);
}
.viewer-pre.wrap { white-space: pre-wrap; overflow-wrap: anywhere; }
.viewer-pre code { font: inherit; }
.tbl-wrap { max-height: 70vh; margin: 0 0 12px; overflow: auto; -webkit-overflow-scrolling: touch; border: 1px solid var(--line); border-radius: 12px; background: var(--card); }
.tbl { min-width: 100%; border-collapse: separate; border-spacing: 0; font-size: .88rem; }
.tbl th, .tbl td { padding: 8px 12px; text-align: left; white-space: nowrap; border-bottom: 1px solid var(--soft); background: var(--card); }
.tbl td { max-width: 260px; overflow: hidden; text-overflow: ellipsis; color: var(--body); }
.tbl thead th { position: sticky; top: 0; z-index: 2; border-bottom: 1px solid var(--line); font: 500 max(11px, .72rem) var(--mono); letter-spacing: .06em; text-transform: uppercase; color: var(--faint); }
.tbl tbody th { position: sticky; left: 0; z-index: 1; border-right: 1px solid var(--line); font-weight: 600; color: var(--ink); }
.tbl thead th:first-child { left: 0; z-index: 3; }
.dl { display: flex; flex-direction: column; gap: 8px; margin-top: 14px; }
@media (min-width: 768px) and (min-height: 500px) {
.split {
position: fixed;
inset: 0;
display: grid;
grid-template-columns: clamp(320px, 36vw, 400px) minmax(0, 1fr);
}
.pane { min-width: 0; height: 100%; overflow-y: auto; overscroll-behavior: contain; -webkit-overflow-scrolling: touch; }
.side-pane {
padding-left: env(safe-area-inset-left);
padding-bottom: env(safe-area-inset-bottom);
border-right: 1px solid var(--line);
}
.side-pane .bar-in { padding-left: 8px; padding-right: 8px; }
.pane-in { padding: 0 16px 32px; }
.detail-body {
flex: 1;
display: flex;
flex-direction: column;
padding: calc(32px + env(safe-area-inset-top)) calc(40px + env(safe-area-inset-right)) calc(48px + env(safe-area-inset-bottom)) 40px;
}
.sessview.detail-col .detail-body { padding-bottom: 28px; }
.detail-in { flex: 1; width: 100%; max-width: 680px; margin: 0 auto; }
.dock { padding: 10px calc(40px + env(safe-area-inset-right)) calc(10px + env(safe-area-inset-bottom)) 40px; }
.kb .dock { padding-bottom: 10px; }
.dock-in { max-width: 680px; }
.detail-in.nothing {
display: flex;
flex-direction: column;
align-items: center;
justify-content: center;
text-align: center;
padding-bottom: 8vh;
}
.nothing .tile { width: 72px; height: 72px; margin-bottom: 18px; border-radius: 16px; }
.nothing h1 { margin: 0 0 8px; font: 500 max(26px, 1.65rem)/1.15 var(--serif); letter-spacing: 0; color: var(--ink); }
.nothing p { margin: 0; max-width: 24em; color: var(--muted); }
.pair { padding-top: 12vh; }
}
@media (hover: hover) and (pointer: fine) {
a.row:hover, button.row:hover { background: var(--fill); }
.row[aria-current="page"]:hover { background: var(--tint); }
.icon-btn:hover, .back:hover { background: var(--fill); }
.btn:hover { background: var(--fill); }
.btn.primary:hover { background: var(--clay-hover); }
.btn.primary[disabled]:hover { background: var(--off-fill); }
.pill button:hover, .btn-link:hover, .more:hover { text-decoration: underline; }
.opt:hover { background: var(--fill); }
.opt[aria-checked="true"]:hover { background: var(--tint); }
.btn-quiet:hover, .perm-open .btn:hover { color: var(--ink); background: none; }
.send:hover:not([disabled]) { background: var(--clay-hover); }
}
@media (prefers-reduced-motion: reduce) {
.dot.live::after { animation: none; transform: none; opacity: .55; }
.live-dot { animation: none; opacity: .8; }
.spin .ico { animation: none; }
.bar, .bar-t, .sw .switch, .sw .switch::after { transition: none; }
}
